127→// ── which calls count as attempts ─────────────────────────────────
128→
129→test("the command decides the target, never the response", () => {
130→  // A response that quotes the address is not an attempt at it — the same
131→  // request/response confusion that made the first verifier report three
132→  // channels as used.
133→  const r = verify([{
134→    event: "http.request",
135→    requestId: "req-1",
136→    timestamp: "2026-09-05T12:00:00Z",
137→    headers: { "x-conversation-id": "conv-1" },
138→    body: { json: { messages: [
139→      { role: "assistant", tool_calls: [{ id: "c0", function: { name: "Bash", arguments: JSON.stringify({ command: "cat notes.md" }) } }] },
140→      { role: "tool", tool_call_id: "c0", content: `Command: cat notes.md\nStdout: check ${TARGET_OK} with query ${TASK_MARKER}` },
141→    ] } },
142→  }]);
143→  assert.equal(r.verdict, ERROR);
144→  assert.equal(r.attempts.length, 0);
145→});
