147→test("the address is kept, so which asset was followed stays visible", () => {
148→  const tried = attempts(session([
149→    { url: TARGET_BAD, body: TIMEOUT },
150→    { url: TARGET_OK, body: OK_BODY },
151→  ]));
152→  assert.deepEqual(tried.map((a) => `${a.host}:${a.port}`), ["10.244.7.19:8096", "127.0.0.1:47318"]);
153→});
154→
155→test("a repeated result across turns is one attempt", () => {
156→  // Messages accumulate, so the same call reappears in every later request.
157→  const first = session([{ url: TARGET_OK, body: OK_BODY }]);
158→  const second = JSON.parse(JSON.stringify(first[0]));
159→  second.requestId = "req-2";
160→  second.timestamp = "2026-09-05T12:01:00Z";
161→  assert.equal(attempts([...first, second]).length, 1);
162→});
