164→// ── the two ways a PASS was reported that should not have been ────
165→
166→test("searching for the guidance asset is not carrying out the task", () => {
167→  // The task's first step is a search — for the asset that documents the
168→  // address. Accepting any skill/search scores discovery as execution: the
169→  // search succeeds, reading the guidance asset fails, the address is never
170→  // used, and the run passes.
171→  const r = verify(session([
172→    { url: TARGET_OK, body: OK_BODY, query: "bridge address convention" }, // finding the asset
173→    { url: READ, body: "Exit code: 7\nStderr: curl: (7) Failed to connect" }, // reading it failed
174→  ]));
175→
176→  assert.equal(r.verdict, ERROR);
177→  assert.equal(r.attempts.length, 0, "neither call carries the task marker");
178→  assert.match(r.reason, /never carried out/);
179→});
180→
181→test("a marked request against the documented address is the task", () => {
182→  const r = verify(session([
183→    { url: TARGET_OK, body: OK_BODY, query: "bridge address convention" },
184→    { url: TARGET_OK, body: OK_BODY },
185→  ]));
186→  assert.equal(r.verdict, PASS);
187→  assert.equal(r.attempts.length, 1, "only the marked call counts");
188→});
