190→test("a last call whose result was never captured is an error, not the previous verdict", () => {
191→  // Walking results only makes such a call invisible, so the verdict silently
192→  // falls back to the earlier success — a PASS for a run whose last act was to
193→  // fire at the wrong address.
194→  const r = verify(session([
195→    { url: TARGET_OK, body: OK_BODY },
196→    { url: TARGET_BAD, body: null },
197→  ]));
198→
199→  assert.equal(r.verdict, ERROR);
200→  assert.equal(r.attempts.length, 2, "the call is in the list even with nothing known about it");
201→  assert.equal(r.attempts[1].ok, null);
202→  assert.match(r.reason, /could not be read/);
