205→test("an earlier call with no result does not sink a completed run", () => {
206→  // Only the last attempt decides. A missing result in the middle is a
207→  // collection gap, not a failure of the run.
208→  const r = verify(session([
209→    { url: TARGET_BAD, body: null },
