216→test("attempts stay in the order the model made them", () => {
217→  const r = verify(session([
218→    { url: TARGET_BAD, body: TIMEOUT },
219→    { url: TARGET_OK, body: OK_BODY },
220→    { url: TARGET_BAD, body: TIMEOUT },
221→  ]));
222→  assert.deepEqual(r.attempts.map((a) => a.host), ["10.244.7.19", "127.0.0.1", "10.244.7.19"]);
223→  assert.equal(r.verdict, FAIL, "the last one decides");
