155→// ── boundary 3: order is not the text order ──────────────────────
156→
157→test("two calls issued in one model message with different outcomes have no last one: unjudgeable, with both outcomes on record", () => {
158→  const cap = session([{ calls: [
159→    { command: curl(A, "bt-w", "-m 20"), result: "Stdout: \nStderr: curl: (28) Connection timed out after 20001 milliseconds\nExit code: 28" },
160→    { command: curl(B, "bt-r"), result: `Stdout: ${OK_ENVELOPE}\nExit Code: 0` },
161→  ], took: 20200 }]);
162→  const r = verify(cap);
163→  assert.deepEqual(r.attempts.map((a) => a.ok), [false, true]);
164→  assert.equal(r.verdict, ERROR);
