181→test("a marked request against the documented address is the task", () => {
182→  const r = verify(session([
183→    { url: TARGET_OK, body: OK_BODY, query: "bridge address convention" },
184→    { url: TARGET_OK, body: OK_BODY },
185→  ]));
186→  assert.equal(r.verdict, PASS);
187→  assert.equal(r.attempts.length, 1, "only the marked call counts");
