  1→/**
  2→ * Provenance event builder — puts "who wrote it" and "who used it" on one record.
  3→ *
  4→ * The existing telemetry is missing that edge. `tool_call_logs` records only the
  5→ * consumer (user_id / agent_id); the asset's owner lives in the asset record, and
  6→ * the two were never joined. Without the edge neither the team dimension nor
  7→ * author confidence can be computed — and it cannot be backfilled later, because
  8→ * asset ownership changes and versions roll forward, so a lookup after the fact
  9→ * returns a different row than the one that was actually used.
 10→ *
 11→ * Each of the three inputs answers only part of the question:
 12→ *
 13→ *   asset pool snapshot   who wrote it, when, which version
 14→ *   tool_call_logs        who used it, whether the call succeeded
 15→ *                         (written by the service itself; the model cannot alter it)
 16→ *   capture JSONL         which asset ids came back in the response
 17→ *
 18→ * That last one is the crux: a `skill/search` bridge row records the request only,
 19→ * so it holds the query but not what was returned. Asset identity can therefore be
 20→ * recovered only from the captured response. Each event records how the fetch was
 21→ * witnessed in `observation`:
 22→ *
 23→ *   bridge+wire   service-side success record AND an asset id parsed from the
 24→ *                 capture (strongest)
 25→ *   bridge_only   service-side success, but the capture missed it — only the
 26→ *                 channel is known
 27→ *   wire_only     an asset id in the capture with no matching service-side
 28→ *                 success record (doubtful)
 29→ *
 30→ * Usage:
 31→ *   node evaluation/provenance/build-events.mjs \
 32→ *     evaluation/provenance/artifacts/asset-pool-snapshot.json \
 33→ *     evaluation/gate0/artifacts/tool-call-logs.jsonl \
 34→ *     [capture.jsonl ...]
 35→ */
 36→
 37→import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
 38→import { createHash } from "node:crypto";
 39→import { dirname } from "node:path";
 40→
 41→/**
 42→ * Stable event id, referenced by gate decisions (`evidence_refs`) and receipts.
 43→ * Derived from content rather than generated randomly, so re-running over the
 44→ * same input yields the same ids and the two sides can be reconciled.
 45→ */
 46→export function eventId(parts) {
 47→  const digest = createHash("sha1").update(parts.join("|")).digest("hex");
 48→  return `evt-${digest.slice(0, 12)}`;
 49→}
 50→
 51→/** Relation between consumer and producer. Only cross_user is team value. */
 52→export function classifyRelation(producer, actor) {
 53→  const pu = producer.user_id || "";
 54→  const pa = producer.agent_id || "";
 55→  const au = actor.user_id || "";
 56→  const aa = actor.agent_id || "";
 57→
 58→  // If either identity is missing the relation is undecidable. Report unknown
 59→  // rather than defaulting to self — defaulting would quietly erase genuine
 60→  // cross-person use.
 61→  if (!pu || !au) return "unknown";
 62→  if (pu !== au) return "cross_user";
 63→  if (pa && aa && pa !== aa) return "cross_agent";
 64→  return "self";
 65→}
 66→
 67→/**
 68→ * The proxy prefixes session_key with the client name (codebuddy:xxx) while the
 69→ * knowledge service stores the bare x-conversation-id. Normalise before joining.
 70→ */
 71→export function normalizeSessionKey(key) {
 72→  const s = String(key ?? "");
 73→  const idx = s.indexOf(":");
 74→  return idx >= 0 ? s.slice(idx + 1) : s;
 75→}
 76→
 77→/** Parse JSONL line by line, skipping malformed lines instead of failing whole. */
 78→export function parseJsonl(text) {
 79→  const rows = [];
 80→  for (const line of String(text).split("\n")) {
 81→    if (!line.trim()) continue;
 82→    try { rows.push(JSON.parse(line)); } catch { /* skip malformed line */ }
 83→  }
 84→  return rows;
 85→}
