102→/** Collect the system prompt text from either OpenAI or Anthropic shaped bodies. */
103→export function extractSystemText(body) {
104→  const parts = [];
105→  if (typeof body?.system === "string") parts.push(body.system);
106→  else if (Array.isArray(body?.system)) parts.push(textOf(body.system));
107→  for (const message of Array.isArray(body?.messages) ? body.messages : []) {
108→    if (message?.role === "system") parts.push(textOf(message.content));
109→  }
110→  return parts.join("\n");
111→}
